                }
            } else {
                throw new IllegalArgumentException("Invalid surrogate pair");
            }
        } else {
            writeByte(lb, (byte) (0xe0 | (c >> 12)), size++);
            writeByte(lb, (byte) (0x80 | ((c >> 6) & 0x3f)), size++);
            writeByte(lb, (byte) (0x80 | (c & 0x3f)), size++);
        }

        if (size == lb.buffer.length) {
            lb = session.next(lb, 8);
            size = lb.start;
        }
    }

    lb.start = size;
    return lb;
