public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }

    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++;
    }

    while (!isPrime(candidate)) {
        candidate += 2;
    }

    if (desiredCapacity >= 1000 && candidate > desiredCapacity * 1.11) {
        candidate = findClosePrime(desiredCapacity);
    }

    return candidate;
}

private static boolean isPrime(int num) {
    if (num <= 1) {
        return false;
    }
    if (num <= 3) {
        return true;
    }
    if (num % 2 == 0 || num % 3 == 0) {
        return false;
    }
    for (int i = 5; i * i <= num; i += 6) {
        if (num % i == 0 || num % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

private static int findClosePrime(int desiredCapacity) {
    int lowerBound = (int) (desiredCapacity * 0.89);
    int upperBound = desiredCapacity;

    for (int i = upperBound; i >= lowerBound; i--) {
        if (isPrime(i)) {
            return i;
        }
    }

    return nextPrime(upperBound);
}

