private String parseToken(final char[] terminators) {
    if (terminators == null || terminators.length == 0) {
        throw new IllegalArgumentException("Terminators array cannot be null or empty");
    }

    StringBuilder tokenBuilder = new StringBuilder();
    int currentChar;
    try {
        while (scanner.hasNext()) {
            currentChar = scanner.next();
            boolean isTerminator = false;
            for (char terminator : terminators) {
                if (currentChar == terminator) {
                    isTerminator = true;
                    break;
                }
            }
            if (isTerminator) {
                break;
            }
            tokenBuilder.append((char) currentChar);
        }
    } catch (Exception e) {
        throw new RuntimeException("Error parsing token", e);
    }

    return tokenBuilder.toString();
}

