private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null) {
        throw new IllegalArgumentException("Input list cannot be null");
    }

    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0L;
    long currentSuffixSum = 0L;

    for (int i = bounds.size() - 1; i >= 0; i--) {
        int value = bounds.get(i);
        if (value < 0) {
            throw new IllegalArgumentException("List elements cannot be negative");
        }
        currentSuffixSum += value;
        suffixSum.add((int) currentSuffixSum);
        totalSum += value;
    }

    Collections.reverse(suffixSum);
    return new Pair<>(suffixSum, totalSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array must not be null");
    }
    if (from < 0 || to >= arr.length || from > to) {
        throw new IllegalArgumentException("Invalid from or to index");
    }
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

