private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    try {
        char firstChar = descriptor.charAt(0);
        if (firstChar == '(') { // method descriptor
            int endParenIndex = descriptor.indexOf(')');
            if (endParenIndex == -1) {
                throw new IllegalArgumentException("Invalid method descriptor: missing closing ')'");
            }
            String argTypes = descriptor.substring(1, endParenIndex);
            int index = 0;
            while (index < argTypes.length()) {
                char typeChar = argTypes.charAt(index);
                switch (typeChar) {
                    case 'B':
                    case 'C':
                    case 'F':
                    case 'I':
                    case 'S':
                    case 'Z':
                        // These types occupy one slot in the stack frame
                        index++;
                        break;
                    case 'D':
                    case 'J':
                        // These types occupy two slots in the stack frame
                        index += 2;
                        break;
                    case 'L':
                    case '[':
                        // Object or array reference types occupy one slot
                        int semiColonIndex = argTypes.indexOf(';', index);
                        if (semiColonIndex == -1) {
                            throw new IllegalArgumentException("Invalid type descriptor: missing ';'");
                        }
                        index = semiColonIndex + 1;
                        break;
                    default:
                        throw new IllegalArgumentException("Invalid type character in descriptor: " + typeChar);
                }
            }
        } else { // field descriptor
            switch (firstChar) {
                case 'B':
                case 'C':
                case 'F':
                case 'I':
                case 'S':
                case 'Z':
                    // These types occupy one slot in the stack frame
                    break;
                case 'D':
                case 'J':
                    // These types occupy two slots in the stack frame
                    break;
                case 'L':
                case '[':
                    // Object or array reference types occupy one slot
                    if (descriptor.indexOf(';') == -1) {
                        throw new IllegalArgumentException("Invalid type descriptor: missing ';'");
                    }
                    break;
                default:
                    throw new IllegalArgumentException("Invalid type character in descriptor: " + firstChar);
            }
        }
    } catch (StringIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid descriptor format", e);
    }
}

