public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path cannot be null");
    }

    try {
        // Normalize the paths to handle any ".." or "." segments
        Path basePath = Path.of(path).normalize();
        Path relPath = Path.of(relativePath).normalize();

        // Resolve the relative path against the base path
        Path resultPath = basePath.resolve(relPath).normalize();

        // Convert the result path back to a string
        return resultPath.toString();
    } catch (InvalidPathException e) {
        throw new IllegalArgumentException("Invalid path provided", e);
    }
}

